import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = {}
    min_heap = []

    for i in range(N):
        for j in range(N):
            heapq.heappush(min_heap, (grid[i][j], i, j))

    while min_heap and k > 0:
        val, x, y = heapq.heappop(min_heap)
        if (x, y) not in visited:
            visited[(x, y)] = True
            k -= 1
            if k > 0:
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < N and 0 <= ny < N:
                        heapq.heappush(min_heap, (grid[nx][ny], nx, ny))
    return [grid[x][y] for x, y in sorted(visited.keys())]

# Examples
print(minPath([ [1,2,3], [4,5,6], [7,8,9]], 3))  # Output: [1, 2, 1]
print(minPath([ [5,9,3], [4,1,6], [7,8,2]], 1))  # Output: [1]
