from heapq import heappop, heappush
from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    min_heap = []
    for i in range(N):
        for j in range(N):
            heappush(min_heap, (grid[i][j], (i, j)))

    visited = defaultdict(lambda: defaultdict(int))
    while k > 0:
        current_value, position = heappop(min_heap)
        i, j = position
        visited[i][j] += 1
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and visited[ni][nj] < 1:
                heappush(min_heap, (grid[ni][nj], (ni, nj)))
        k -= 1

    path = []
    for i in range(N):
        for j in range(N):
            if visited[i][j] == 1:
                path.append(grid[i][j])

    return path[:k]
```

