from itertools import product
from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    values = {(i, j): grid[i][j] for i, j in product(range(N), repeat=2)}

    def neighbors(x, y):
        for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def dfs(x, y, path, visited):
        if len(path) == k:
            paths.append(path)
            return
        for nx, ny in neighbors(x, y):
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                dfs(nx, ny, path + [values[nx, ny]], visited)
                visited.remove((nx, ny))

    paths = []
    for i in range(N):
        for j in range(N):
            visited = set([(i, j)])
            dfs(i, j, [values[i, j]], visited)

    paths.sort()
    return paths[0]
