def valid_date(date):
    import re
    date_pattern = re.compile(r"^(1[0-2]|0[1-9])-(3[01]|[12][0-9]|0[1-9])-([0-9]{4})$")
    if not date_pattern.match(date):
        return False
    month, day, year = map(int, date.split('-'))
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 1 <= day <= 31
    elif month in [4, 6, 9, 11]:
        return 1 <= day <= 30
    elif month == 2:
        return 1 <= day <= 29
    return False
