def valid_date(date):
    import re
    date_pattern = re.compile(r"(0[1-9]|1[0-2])-(0[1-9]|1[0-9]|2[0-9]|3[01])-(\d{4})")
    match = date_pattern.match(date)
    if not match:
        return False
    month, day, year = match.groups()
    month, day, year = int(month), int(day), int(year)
    if month < 1 or month > 12:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False
    return True
