def valid_date(date):
    import re
    date_pattern = re.compile(r"(0[1-9]|1[0-2])-([0-2][0-9]|3[01]|0[0-9])-([0-9]{4})")
    match = date_pattern.match(date)
    if not match:
        return False
    month, day, year = match.groups()
    month, day, year = int(month), int(day), int(year)
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if month in [4, 6, 9, 11] and day > 30:
        return False
    if month == 2 and day > 29:
        return False
    return True
