from typing import List, Tuple


def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    from itertools import pairwise
    from math import isnan

    numbers.sort()
    closest = (numbers[0], numbers[1])
    min_diff = float('inf')

    for a, b in pairwise(numbers):
        if b - a < min_diff:
            min_diff = b - a
            closest = (a, b)

    return closest if not arenan(closest[0]) and not arenan(closest[1]) else (numbers[0], numbers[1])

def arenan(x):
    return isinstance(x, float) and isnan(x)

