def count_nums(arr):
    def sum_of_digits(n):
        result = 0
        is_negative = n < 0
        for digit in str(abs(n)):
            if is_negative and digit == str(n)[1]:
                result -= int(digit)
            else:
                result += int(digit)
        return result if result != 0 else 1

    return sum(1 for num in arr if sum_of_digits(num) > 0)

# Test cases
assert count_nums([]) == 0
assert count_nums([-1, 11, -11]) == 1
assert count_nums([1, 1, 2]) == 3
