def skjkasdkd(lst):
    from math import sqrt

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    def sum_of_digits(n):
        return sum(int(digit) for digit in str(n))

    largest_prime = max((num for num in lst if is_prime(num)), default=None)
    if largest_prime:
        return sum_of_digits(largest_prime)
    return 0
