        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sum_of_digits(n):
        return sum(int(d) for d in str(n))

    max_prime = -1
    for num in lst:
        if is_prime(num) and num > max_prime:
            max_prime = num

    if max_prime > 0:
        return sum_of_digits(max_prime)
    else:
        return 0
