def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if not l:
        return True

    increasin = decreases = False

    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            if decreases:
               return False
        elif l[i] < l[i - 1]:
            if increasin:
                return False
            decreases = True
        else:
            continue

        increasin = True

    return True
```

