def valid_date(date):
    try:
        datetime.strptime(date, '%m-%d-%Y')
        year = int(date[-4:])
        month = int(date[:2])
        day = int(date[3:5])

        if month in [1, 3, 5, 7, 8, 10, 12]:
            if day < 1 or day > 31:
                return False
        elif month in [4, 6, 9, 11]:
            if day < 1 or day > 30:
                return False
        elif month == 2:
            if day < 1 or day > 29:
                return False
        else:
            return False
        if month < 1 or month > 12:
            return False
    except ValueError:
        return False
    return True

