        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def sum_of_digits(n):
        return sum(int(d) for d in str(n))

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
