def encrypt(s):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            start = ord('a')
            new_pos = (ord(char) - start - 4) % 26
            result += chr(start + new_pos)
        elif 'A' <= char <= 'Z':
            start = ord('A')
            new_pos = (ord(char) - start - 4) % 26
            result += chr(start + new_pos)
        else:
            result += char
    return result
