def encrypt(s):
    import string

    def rotate_char(c):
        if c in string.ascii_lowercase:
            return string.ascii_lowercase[(string.ascii_lowercase.index(c) + (2 * 2)) % 26]
        elif c in string.ascii_uppercase:
            return string.ascii_uppercase[(string.ascii_uppercase.index(c) + (2 * 2)) % 26]
        else:
            return c

    return ''.join(rotate_char(c) for c in s)

