def closest_integer(value):
    num = float(value)
    floored = num - 0.5
    ceiled = num + 0.5
    if num - int(num) == 0.5:
        if num > 0:
            return int(ceiled)
        else:
            return int(floored)
    else:
        return round(num)

# Test cases
