def correct_bracketing(brackets: str):
    """ brackets is a string of "(" and ")".
    return True if every opening bracket has a corresponding closing bracket.

    >>> correct_bracketing("(")
    False
    >>> correct_bracketing("()")
    True
    >>> correct_bracketing("(()())")
    True
    >>> correct_bracketing(")(()")
    False
    """
    stack = 0
    for char in brackets:
        if char == '(':
            stack += 1
        elif char == ')':
            stack -= 1
        if stack < 0:
            return False
    return stack == 0
