def parse_nested_parens(paren_string: str) -> List[int]:
    from collections import defaultdict
    import re

    def max_nested_bracesLevel(braces: str) -> int:
        max_level, current_level = 0, 0
        for char in braces:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1
        return max_level

    return [max_nested_bracesLevel(group) for group in paren_string.split()]
