from itertools import product
from heapq import heappop, heappush

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def get_neighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def dijkstra():
        pq = [(grid[x][y], x, y) for x, y in product(range(N), repeat=2)]
        seen = set()
        path = []

        while pq and len(path) < k:
            value, x, y = heappop(pq)
            if (x, y) in seen:
                continue
            seen.add((x, y))
            path.append(value)
            for nx, ny in get_neighbors(x, y):
                heappush(pq, (grid[nx][ny], nx, ny))

        return path

    return dijkstra()
