def histogram(test):
    from collections import defaultdict

    letter_counts = defaultdict(int)
    max_count = 0
    repeated_letters = set()

    for letter in test.split():
        letter_counts[letter] += 1
        if letter_counts[letter] == max_count:
            repeated_letters.add(letter)
        elif letter_counts[letter] > max_count:
            max_count = letter_counts[letter]
            repeated_letters = {letter}

    result = {letter: max_count for letter in repeated_letters}
    return result
