```python
def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Split the string into a list of letters
    letters = test.split()

    # Initialize a dictionary to store letter counts
    letter_counts = {}

    # Populate the dictionary with counts for each letter
    for letter in letters:
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1

    # Find the maximum count or all counts if they are the same
    max_count = 0
    letters_with_max_count = []
    for letter, count in letter_counts.items():
        if count > max_count:
            max_count = count
            letters_with_max_count = [letter]
        elif count == max_count:
            letters_with_max_count.append(letter)

    # Create the result dictionary containing letters with the maximum count
    result = {}
    for letter in letters_with_max_count:
        result[letter] = max_count

    return result
