def solve(s):
    import string

    def reverse_case(char):
        return char.swapcase() if char.isalpha() else char

    result = list(s)
    for i in range(len(s)):
        result[i] = reverse_case(s[i])

    if result[0].isalpha():
        return ''.join(result)
    else:
        return ''.join(reversed(result))
