def solve(s):
    result = []
    has_letters = False

    for char in s:
        if char.isalpha():
            has_letters = True
            result.append(char.swapcase())
        else:
            result.append(char)

    if not has_letters:
        return s[::-1]
    else:
        return ''.join(result)

# Test cases
