def solve(s):
    import string

    def is_letter(c):
        return c in string.ascii_letters

    if not any(is_letter(c) for c in s):
        return s[::-1]

    result = []
    for c in s:
        if is_letter(c):
            result.append(c.lower() if c.isupper() else c.upper())
        else:
            result.append(c)

    return ''.join(result)
```

