def histogram(test):
    from collections import defaultdict

    letter_counts = defaultdict(int)
    max_count = 0
    letters_with_max_count = set()

    for letter in test.split():
        letter_counts[letter] += 1
        if letter_counts[letter] > max_count:
            max_count = letter_counts[letter]
            letters_with_max_count = {letter}
        elif letter_counts[letter] == max_count:
            letters_with_max_count.add(letter)

    result = {letter: count for letter, count in letter_counts.items() if count == max_count}
    return result
