def count_nums(arr):
    def sum_digits(n):
        is_negative = n < 0
        digit_sum = 0
        for digit in str(n):
            if digit == '-':
                continue
            digit_sum += int(digit) if not is_negative or digit != str(n)[0] else -int(digit)
        return digit_sum if digit_sum > 0 or not is_negative else 0

    return sum(sum_digits(x) > 0 for x in arr)
