def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0
    zero_count = 0

    for num in arr:
        if num == 0:
            zero_count += 1
        else:
            sign_product *= abs(num) / num
            magnitude_sum += abs(num)

    if zero_count > 0:
        return 0
    else:
        return int(sign_product * magnitude_sum)

