def tri(n):
    def even_tri(n):
        return 1 + n // 2

    def odd_tri(n, memo):
        if n in memo:
            return memo[n]
        if n == 1:
            return 3
        memo[n] = even_tri(n) if n % 2 == 0 else odd_tri(n - 1, memo) + odd_tri(n - 2, memo) + odd_tri(n + 1, memo)
        return memo[n]

    result = []
    memo = {}
    for i in range(n + 1):
        result.append(odd_tri(i, memo))
    return result
