def fib4(n: int):
    from typing import Dict

    if n == 0:
        return 0
    elif n in [1, 2]:
        return 0
    elif n == 3:
        return 2

    dp: Dict[int, int] = {0: 0, 1: 0, 2: 2, 3: 0}

    for i in range(4, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3] + dp[i - 4]

    return dp[n]

# Test cases
