import heapq

def minPath(grid, k):
    n = len(grid)
    value_to_position = defaultdict(set)
    for i in range(n):
        for j in range(n):
            value_to_position[grid[i][j]].add((i, j))

    start_positions = value_to_position.pop(min(value_to_position.keys()))

    visited = set()
    min_path = None
    min_path_queue = [(list(value_to_position.keys())[0], start_positions, 0)]

    while min_path_queue:
        path, positions, path_length = heapq.heappop(min_path_queue)
        if path_length == k:
            return path
        for pos in list(positions):
            if pos in visited:
                continue
            visited.add(pos)
            val = grid[pos[0]][pos[1]]
            new_path = path + [val]
            new_pos = set([pos])
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = pos[0] + dx, pos[1] + dy
                if 0 <= nx < n and 0 <= ny < n:
                    new_pos.add((nx, ny))
            heapq.heappush(min_path_queue, (new_path, new_pos, path_length + 1))

            value_to_position[val].remove(pos)
            if not value_to_position[val]:
                del value_to_position[val]
