        i, j, used, path = queue.pop(0)
        if used == k:
            return path
        for p in get_adj((i, j)):
            if (p[0], p[1], used+1) not in seen:
                seen.add((p[0], p[1], used+1))
                queue.append((p[0], p[1], used+1, path + [grid[p[0]][p[1]]]))
