from itertools import product
from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    value_map = {(x, y): grid[x][y] for x, y in product(range(n), repeat=2)}

    def bfs(start):
        queue = deque([(start, [value_map[start]])])
        visited = set([start])
        paths = []
        while queue and len(paths) < k:
            current, path = queue.popleft()
            if len(path) == k:
                paths.append(path[:])
            for dx, dy in directions:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [value_map[(nx, ny)]]))
        return paths

    min_path = None
    for x, y in product(range(n), repeat=2):
        paths = bfs((x, y))
        for path in paths:
            if min_path is None or path < min_path:
                min_path = path
    return min_path
