        if x == 1:
            return [1]
        if x == 0:
            return []
        seq = helper(x - 1)
        if (x + 1) & 1:  # Check if (x + 1) is odd
            seq.append(seq[-1] + seq[-2] + seq[0])
        else:
            seq.append(1 + (x + 1) // 2)
        return seq

