def tri(n):
    if n == 0:
        return [3]
    trib_seq = [3, 1] + [0] * n

    def tri_recursion(k):
        if k == 1:
            return 3
        elif k % 2 == 0:
            return 1 + k // 2
        else:
            return tri_recursion(k - 1) + tri_recursion(k - 2) + tri_recursion(k + 1)

    for j in range(2, n + 1):
        trib_seq[j] = tri_recursion(j + 1)

    return trib_seq
