    seq = [0] * (n + 2)
    seq[1] = 3
    seq[2] = 2
    for i in range(3, n + 2):
        if i % 2 == 0:
            seq[i] = 1 + i // 2
        else:
            seq[i] = seq[i - 1] + seq[i - 2] + seq[-1 if i > 2 else 1]
    return [seq[i] for i in range(1, n + 2)]
