from sympy import isprime

def is_multiply_prime(a):
    if a < 2:
        return False
    count = 0
    for i in range(2, a + 1):
        if a % i == 0 and isprime(i) and isprime(int(a / i)):
            count += 1
            if count > 3:
                return False
            a = int(a / i)
    return count == 3 and a == 1
