from functools import lru_cache

def fibfib(n: int):
    """The FibFib number sequence is a sequence similar to the Fibration sequence that's defined as follows:
    fibfib(0) == 0
    fibfib(1) == 0
    fibfib(2) == 1
    fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3).
    Please write a function to efficiently compute the n-th element of the fibfib number sequence.
    >>> fibfib(1)
    0
    >>> fibfib(5)
    4
    >>> fibfib(8)
    24
    """
    @lru_cache(maxsize=None)
    def compute_fibfib(m):
        if m == 0 or m == 1:
            return 0
        elif m == 2:
            return 1
        else:
            return compute_fibfib(m-1) + compute_fibfib(m-2) + compute_fibfib(m-3)

    return compute_fibfib(n)
```

