def solve(s):
    import string

    def is_letter(c):
        return c in string.ascii_letters

    result = []
    letters = []

    for char in s:
        if is_letter(char):
            letters.append(char)
            result.append(char.swapcase())
        else:
            result.append(char)

    if not any(is_letter(c) for c in s):
        return s[::-1]

    for i, char in enumerate(result):
        if char.isalpha():
            result[i] = letters.pop(0)

    return ''.join(result)
