def unique_digits(x):
    def has_odd_digits(n):
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                return False
            n //= 10
        return True

    unique = [num for num in x if has_odd_digits(num)]
    return sorted(unique)

