def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)
    total_sum = sum(numbers)
    total_product = evaluate_product(numbers)
    return (total_sum, total_product)


def evaluate_product(nums):
    product = 1
    for num in nums:
        product *= num
    return product
