def split_words(txt):
    if txt.isspace() or txt.isalpha():
        return sum(1 for c in txt if (ord(c) - ord('a')) % 2 == 1 and c.islower())
    words = txt.split(' ')
    if not words:
        words = txt.split(',')
    return words if words else [txt]

