def anti_shuffle(s):
    import string

    def sort_word(w):
        return ''.join(sorted(w))

    words = s.split()
    sorted_words = [sort_word(w) for w in words]
    result = []
    word_index = 0
    for char in s:
        if char in string.whitespace:
            result.append(char)
        else:
            result.append(sorted_words[word_index % len(sorted_words)].pop(0))
            if not sorted_words[word_index % len(sorted_words)]:
                word_index += 1

    return ''.join(result)
```

