def get_row(lst, x):
    coordinates = []    
    for row_index, row in enumerate(lst):
        for col_index, elem in enumerate(row):
            if elem == x:
                coordinates.append((row_index, col_index))
    coordinates.sort(key=lambda c: (c[0], -c[1]))    
    return coordinates
```

```python
def get_row(lst, x):
    res = []
    for i in range(len(lst)):
        for j in range(len(lst[i])):
            if lst[i][j] == x:
                res.append((i, j))
    return sorted(res, key=lambda k: (k[0], -k[1]))

# Examples
print(get_row([
  [1,2,3,4,5,6],
  [1,2,3,4,1,6],
  [1,2,3,4,5,1]
], 1))  # == [(0, 0), (1, 4), (1, 0), (2, 5), (2, 0)]
print(get_row([], 1))  # == []
print(get_row([[], [1], [1, 2, 3]], 3))  # == [(2, 2)]
```

