def exchange(lst1, lst2):
    if all(x % 2 == 0 for x in lst1):
        return "YES"
    for odd in [x for x in lst1 if x % 2 != 0]:
        if any(x % 2 == 0 for x in lst2):
            return "YES"
        lst2.append(odd)
        lst1.remove(odd)
    return "NO"
