def match_parens(lst):
    def is_good(s):
        balance = 0
        for char in s:
            if balance < 0:
                return False
            if char == '(':
                balance += 1
            else:
                balance -= 1
        return balance == 0

    string1, string2 = lst[0], lst[1]
    if is_good(string1) or is_good(string2) or (is_good(string1 + string2) or is_good(string2 + string1)):
        return 'Yes'
    else:
        return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Expected output: 'Yes'
print(match_parens([')', ')']))    # Expected output: 'No'
