def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    word = reversed(word)
    for i, char in enumerate(word):
        if i == 0 or i == len(word) - 1:
            continue
        if char in vowels and next((c for c in word if c not in vowels and next(word, None) in vowels), None):
            return char
    return ''
```

