def is_sorted(lst):
    if len(lst) <= 1:
        return True
    prev = lst[0]
    duplicates = False
    for i in lst[1:]:
        if i < prev:
            return False
        if i == prev and len(lst) > 2 and lst[i-2] == lst[i-1]:
            duplicates = True
        prev = i
    return not duplicates if duplicates else True
```

