def valid_date(date):
    import re
    date_pattern = re.compile(r'^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-([0-9]{4})$')
    if not date_pattern.match(date):
        return False
    month, day, year = map(int, date.split('-'))
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if month in [9, 4, 6, 11] and day > 30:
        return False
    if month == 2 and day > 29:
        return False
    return True
```

