        datetime.strptime(date, '%m-%d-%Y')
        month, day, year = map(int, date.split('-'))
        if month in [1, 3, 5, 7, 8, 10, 12]:
            if 1 <= day <= 31:
                return True
            else:
                return False
        elif month in [4, 6, 9, 11]:
            if 1 <= day <= 30:
                return True
            else:
                return False
        elif month == 2:
            if 1 <= day <= 29:
                return True
            else:
                return False
        elif month < 1 or month > 12:
            return False
    except ValueError:
        return False
