def histogram(test):
    from collections import defaultdict

    if not test:
        return {}

    letter_counts = defaultdict(int)
    max_count = 0
    occurrences = defaultdict(list)

    for letter in test.split():
        letter_counts[letter] += 1
        if letter_counts[letter] > max_count:
            max_count = letter_counts[letter]
        occurrences[letter_counts[letter]].append(letter)

    return dict((count, letters) for count, letters in occurrences.items() if count == max_count)

# Example usage:
print(histogram('a b c'))  # {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # {'b': 4}
print(histogram(''))  # {}
```

