def tri(n):
    if n == 0:
        return [1]
    if n == 1:
        return [1, 3]

    sequence = [1, 3]

    def trib(n):
        if n == 1:
            return 3
        elif n % 2 == 0:
            return 1 + n // 2
        else:
            return trib(n - 1) + trib(n - 2) + trib(n + 1)

    for i in range(2, n + 1):
        sequence.append(trib(i + 1))

    return sequence
