def tri(n):
    if n == 0:
        return [3]
    elif n == 1:
        return [1, 3]
    sequence = [1, 3, 2] + [0] * (n - 2)
    for i in range(3, n + 1):
        if i % 2 == 0:
            sequence[i] = 1 + i // 2
        else:
            sequence[i] = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]
    return sequence[:n + 1]
