def histogram(test):
    from collections import defaultdict

    letter_counts = defaultdict(int)
    max_count = 0
    counts = []

    for letter in test.split():
        letter_counts[letter] += 1
        if letter_counts[letter] > max_count:
            max_count = letter_counts[letter]
            counts = [letter]
        elif letter_counts[letter] == max_count:
            counts.append(letter)

    return {letter: count for letter, count in letter_counts.items() if count == max_count or letter in counts}

# Test cases
