def closest_integer(value):
    num = float(value)
    floor = num - (num < 0)  # Subtracts half towards zero if num is negative
    ceil = num + (num >= 0)  # Adds half away from zero if num is positive
    if num - floor <= ceil - num:
        return int(floor)
    else:
        return int(ceil)

