def closest_integer(value):
    num = float(value)
    integral, fractional = divmod(num, 1)
    if fractional < 0.5:
        return int(num) if num > 0 else int(num) - 1
    elif fractional > 0.5:
        return int(num) + 1 if num > 0 else int(num)
    else:
        return int(num) + 1 if num > 0 else int(num)

