def histogram(test):
    from collections import defaultdict

    if not test:
        return {}

    letter_counts = defaultdict(int)
    max_count = 0
    counts = defaultdict(int)

    for letter in test.split():
        letter_counts[letter] += 1
        if letter_counts[letter] > max_count:
            max_count = letter_counts[letter]
        counts[letter_counts[letter]] += 1

    if counts[max_count] == 1:
        return {letter: max_count for letter in letter_counts if letter_counts[letter] == max_count}
    else:
        return {count: count for count in counts if count == max_count}

# Test cases
