def histogram(test):
    from collections import defaultdict

    if not test:
        return {}

    word_list = test.split()
    freq = defaultdict(int)

    for word in word_list:
        freq[word] += 1

    max_count = max(freq.values())
    result = {k: v for k, v in freq.items() if v == max_count}

    return result
