from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    stack, results = [], []
    for char in paren_string.replace(' ', ''):
        if char == '(':
            stack.append(1)
            results.append(max(results[-1] + 1, 1) if results else 1)
        else:
            stack.pop()
            results.append(max(results[-1] - 1, 0))
    return results
