def even_odd_count(num):
    from collections import defaultdict
    num_str = str(abs(num))
    counts = defaultdict(int)
    for digit in num_str:
        if int(digit) % 2 == 0:
            counts['even'] += 1
        else:
            counts['odd'] += 1
    return (counts['even'], counts['odd'])
