from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    parens = []
    stack = []
    start_index = 0

    for i, char in enumerate(paren_string.replace(" ", "")):
        if char == '(':
            if not stack:
                start_index = i
            stack.append(char)
        elif char == ')':
            stack.pop()
            if not stack:
                parens.append(paren_string[start_index:i+1])

    return [group for group in parens if group]  # Filter out any empty strings
