    start = next((i for i, x in enumerate(planets) if x == planet1), None)
    end = next((i for i, x in enumerate(planets) if x == planet2), None)

    if start is None or end is None or start >= end:
        return ()

    return tuple([planets[i] for i in range(start + 1, end)])
