def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if x == 1:
        return True
    power = 0
    temp_x = x
    while temp_x <= x:
        temp_x = n ** power
        if temp_x == x:
            return True
        power += 1
    return False
